UPDATE T_MARKET_ITEM
   SET  CATEGORY    = #{category}
       ,TITLE       = #{title}
       ,PRICE       = #{price}
       ,DESCRIPTION = #{description}
       ,ITEM_COND   = #{cond}
       ,TRADE_TYPE  = #{tradeType}
       ,REGION      = #{region}
       ,UPD_DAY     = NOW()
 WHERE 1=1
   AND ID = #{id}
   AND SELLER_ID = #{sellerId}
   AND DEL_DAY IS NULL

mapper.select:
SELECT
FROM T_MARKET_ITEM I JOIN T_USER U ON U.ID = I.SELLER_ID
JOIN T_MARKET_LIKE ML ON ML.ITEM_ID = I.ID AND ML.USER_ID = #{likedBy}
WHERE 1=1 AND I.DEL_DAY IS NULL AND U.DEL_DAY IS NULL
AND I.SELLER_ID = #{sellerId}
AND I.STATUS <> 'HIDDEN'
AND I.STATUS <> 'HIDDEN'
AND I.CATEGORY = #{category}
AND I.STATUS = 'SALE'
AND I.PRICE = 0
AND (I.TITLE ILIKE '%' || #{q} || '%' OR I.DESCRIPTION ILIKE '%' || #{q} || '%')
AND I.ID <> #{exceptId}
ORDER BY
I.PRICE ASC, I.BUMP_DAY DESC I.PRICE DESC, I.BUMP_DAY DESC (I.LIKE_CNT * 3 + I.CHAT_CNT * 5 + I.VIEW_CNT) DESC, I.BUMP_DAY DESC I.BUMP_DAY DESC, I.ID DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE T_MARKET_ITEM
   SET  STATUS   = #{status}
       ,BUYER_ID = CASE WHEN #{status} = 'SOLD' THEN BUYER_ID ELSE NULL END
       ,UPD_DAY  = NOW()
 WHERE 1=1
   AND ID = #{id}
   AND SELLER_ID = #{sellerId}
   AND DEL_DAY IS NULL
   AND STATUS <> 'HIDDEN'

UPDATE T_MARKET_ITEM
   SET DEL_DAY = NOW()
 WHERE 1=1
   AND ID = #{id}
   AND DEL_DAY IS NULL

   AND SELLER_ID = #{sellerId}

UPDATE T_MARKET_ITEM
   SET LIKE_CNT = (SELECT COUNT(*) FROM T_MARKET_LIKE L WHERE L.ITEM_ID = #{itemId})
 WHERE ID = #{itemId}

UPDATE T_MARKET_ITEM
   SET  STATUS   = 'SOLD'
       ,BUYER_ID = #{buyerId,jdbcType=BIGINT}
       ,UPD_DAY  = NOW()
 WHERE 1=1
   AND ID = #{id}
   AND SELLER_ID = #{sellerId}
   AND DEL_DAY IS NULL
   AND STATUS <> 'HIDDEN'
